  /* clients preview: only the first two rows of logos */
  function fitLogos() {
    var g = $('logosPrev'); if (!g) return;
    var items = g.children, i;
    for (i = 0; i < items.length; i++) items[i].hidden = false;
    var cols = getComputedStyle(g).gridTemplateColumns.split(' ').length || 6;
    for (i = 0; i < items.length; i++) items[i].hidden = i >= cols * 2;
  }
  fitLogos();
  var rt; window.addEventListener('resize', function () { clearTimeout(rt); rt = setTimeout(fitLogos, 150); });
  window.addEventListener('load', fitLogos);

  /* ---------- language switch ---------- */
  var root = document.documentElement;
  function setLang(l) {
    root.lang = l; root.dir = l === 'ar' ? 'rtl' : 'ltr';
    $('lang').textContent = l === 'ar' ? 'EN' : 'عربي';
    document.querySelectorAll('[data-ph-ar]').forEach(function (i) {
      i.placeholder = i.getAttribute('data-ph-' + l); i.setAttribute('aria-label', i.placeholder);
    });
    try { localStorage.setItem('lang', l); } catch (e) {}
  }
  $('lang').addEventListener('click', function () { setLang(root.lang === 'ar' ? 'en' : 'ar'); });
  var saved = 'ar'; try { saved = localStorage.getItem('lang') || 'ar'; } catch (e) {}
  setLang(saved);

